#include "web.cpp"
int main(){string id;while(cin>>id){double p[35];for(double&v:p)cin>>v;Hero h;Scenario sc;Build b;int aug;Options o;auto err=configure(p,35,h,sc,b,aug,o);if(!err.empty()){cerr<<err;return 1;}int pass= -1,fail=0;cout<<"{\"id\":\""<<id<<"\",\"stages\":[";bool first=true;auto run=[&](int d){o.dps=d;Sim sim(h,sc,b,aug,o);sim.capture=false;auto r=sim.run();if(!first)cout<<',';first=false;cout<<"{\"dps\":"<<d<<",\"result\":";outputResult(cout,r,17);cout<<'}';return r.alive;};for(int d=300;d<=5000;d+=50){if(!run(d)){fail=d;break;}pass=d;}if(!fail)return 2;int score=pass;for(int d=pass<300?300:pass+1;d<fail;d++){if(!run(d))break;score=d;}cout<<"],\"score\":"<<score<<",\"coarsePass\":"<<pass<<",\"coarseFail\":"<<fail<<"}"<<endl;}}
